def mask_secret(secret, visible=4):
    """Mask middle of secret; keep first/last `visible` chars."""
    if len(secret) <= visible * 2:
        return "*" * len(secret)
    # TODO: middle mask
    return secret

code.tests:
def __check(name, ok, msg=""):
    __results.append({"name": name, "pass": bool(ok), "msg": msg})

try:
    m = mask_secret("sk-ant-api03-abcdefghijklmnop", 4)
    __check("starts", m.startswith("sk-a"))
    __check("ends", m.endswith("mnop"))
    __check("masked", "*" in m[4:-4])
    __check("short", mask_secret("abc", 4) == "***")
except Exception as e:
    __check("runtime", False, str(e))
